<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
require __DIR__.'/../php/bootstrap.php';
$db->exec(file_get_contents(__DIR__.'/../php/watch-schema.sql'));
function watch_list():array{$series=rows('SELECT s.id,s.title,s.is_ongo isOngoing,MAX(CAST(c.number AS REAL)) maxChapter FROM series s LEFT JOIN chapters c ON c.series_id=s.id GROUP BY s.id ORDER BY s.title');foreach($series as &$s)$s['mappedSources']=rows('SELECT url,title FROM chapter_watch_sources WHERE series_id=?',[$s['id']]);return ['recipient'=>one("SELECT value FROM chapter_watch_config WHERE key='recipient'")['value']??null,'sources'=>['https://mangaplus.shueisha.co.jp/updates','https://mangafire.to/'],'series'=>$series,'lastRun'=>one('SELECT checked_at,report_json FROM chapter_watch_runs ORDER BY id DESC LIMIT 1')];}
function source_url(string $url):string{$p=parse_url($url);if(!$p||($p['scheme']??'')!=='https'||!in_array($p['host']??'',['mangaplus.shueisha.co.jp','mangafire.to'],true)||isset($p['user'])||isset($p['pass'])||isset($p['port']))throw new RuntimeException('Only approved HTTPS sources allowed.');return $url;}
function title_key(string $s):string{return preg_replace('/[^\p{L}\p{N}]/u','',mb_strtolower(preg_replace('/\p{Mn}/u','',Normalizer::normalize($s,Normalizer::FORM_KD))));}
try{
 $command=$argv[1]??'';$arg=$argv[2]??'';$result=null;
 if($command==='list')$result=watch_list();
 elseif($command==='pending'){$events=rows('SELECT e.id,e.number,e.source_url sourceUrl,e.chapter_url chapterUrl,e.observed_at observedAt,s.title FROM chapter_watch_events e JOIN series s ON s.id=e.series_id WHERE e.notified_at IS NULL ORDER BY e.id');foreach($events as &$e)$e['notificationKey']='two-manga-release-'.$e['id'];$result=['recipient'=>watch_list()['recipient'],'events'=>$events];}
 elseif($command==='recipient'){if(!filter_var($arg,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Valid explicit recipient required.');q("INSERT INTO chapter_watch_config VALUES('recipient',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",[$arg]);$result=['ok'=>true];}
 elseif(in_array($command,['ingest','map','sent','record-run'])){
  $input=json_decode(file_get_contents($arg),true,512,JSON_THROW_ON_ERROR);
  if($command==='record-run'){q('INSERT INTO chapter_watch_runs(checked_at,report_json) VALUES(?,?)',[now_iso(),json_encode($input,JSON_UNESCAPED_UNICODE)]);$result=['ok'=>true];}
  elseif($command==='sent'){if(($input['recipient']??null)!==watch_list()['recipient']||empty($input['messageId'])||empty($input['eventIds']))throw new RuntimeException('Actual delivery receipt required.');transaction(function()use($input){foreach($input['eventIds'] as $id)q('UPDATE chapter_watch_events SET notified_at=?,recipient=?,message_id=? WHERE id=? AND notified_at IS NULL',[now_iso(),$input['recipient'],$input['messageId'],(int)$id]);});$result=['ok'=>true];}
  elseif($command==='map'){$url=source_url($input['url']);if(!one('SELECT 1 FROM series WHERE id=?',[(int)$input['seriesId']])||mb_strlen($input['verification']??'')<20||empty($input['title'])||!preg_match('~^/(titles/\d+|title/[^/]+)/?$~D',parse_url($url,PHP_URL_PATH)))throw new RuntimeException('Verified title page required.');q('INSERT INTO chapter_watch_sources VALUES(?,?,?) ON CONFLICT(series_id,url) DO UPDATE SET title=excluded.title',[(int)$input['seriesId'],$url,$input['title']]);q('INSERT INTO chapter_watch_runs(checked_at,report_json) VALUES(?,?)',[now_iso(),json_encode(['mappingVerified'=>$input])]);$result=['ok'=>true];}
  else{
   if(!is_array($input)||!array_is_list($input)||count($input)>500)throw new RuntimeException('Explicit observations required.');$catalog=watch_list()['series'];$records=[];
   foreach($input as $item){$work=null;foreach($catalog as $w)if($w['id']===(int)$item['seriesId'])$work=$w;if(!$work)throw new RuntimeException('Unknown work.');$url=source_url($item['sourceUrl']);$aliases=[$work['title']];foreach($work['mappedSources'] as $alias)if(parse_url($alias['url'],PHP_URL_HOST)===parse_url($url,PHP_URL_HOST))$aliases[]=$alias['title'];if(!in_array(title_key($item['title']),array_map('title_key',$aliases)))throw new RuntimeException('Title not verified.');if(empty($item['chapters'])||count($item['chapters'])>500)throw new RuntimeException('Published chapter list required.');$chapters=[];foreach($item['chapters'] as $c){$number=chapter_numbers($c['number']);if(count($number)!==1||str_contains((string)$c['number'],'/')||str_contains((string)$c['number'],'-'))throw new RuntimeException('Single observed chapter number required.');$link=empty($c['url'])?null:source_url($c['url']);if($link&&parse_url($link,PHP_URL_HOST)!==parse_url($url,PHP_URL_HOST))throw new RuntimeException('Source mismatch.');$chapters[]=['number'=>$number[0],'url'=>$link];}$records[]=compact('work','url','chapters');}
   $added=transaction(function()use($records,$db){$added=[];foreach($records as $r){$work=$r['work'];q('INSERT OR IGNORE INTO chapter_watch_sources VALUES(?,?,?)',[$work['id'],$r['url'],$work['title']]);foreach($r['chapters'] as $c){if(($work['maxChapter']!==null&&(float)$c['number']<=$work['maxChapter'])||one('SELECT 1 FROM chapters WHERE series_id=? AND CAST(number AS REAL)=?',[$work['id'],(float)$c['number']]))continue;$at=now_iso();q('INSERT INTO chapters(series_id,number,is_ongo,created_at) VALUES(?,?,?,?)',[$work['id'],$c['number'],$work['isOngoing'],$at]);$id=(int)$db->lastInsertId();foreach(STAGES as $stage)q("INSERT INTO stages(chapter_id,stage,status) VALUES(?,?,'waiting')",[$id,$stage]);foreach(rows('SELECT d.* FROM series_defaults d JOIN users u ON u.id=d.user_id WHERE d.series_id=? AND u.active=1',[$work['id']]) as $a)if(has_role($a['user_id'],STAGE_ROLES[$a['stage']]))assign_stage(['id'=>$id,'series_id'=>$work['id'],'is_ongo'=>$work['isOngoing']],$a['user_id'],$a['stage'],'fixed',$a['fee_cents']);q('INSERT INTO chapter_watch_events(series_id,chapter_id,number,source_url,chapter_url,observed_at) VALUES(?,?,?,?,?,?)',[$work['id'],$id,$c['number'],$r['url'],$c['url'],$at]);$added[]=['eventId'=>(int)$db->lastInsertId(),'seriesId'=>$work['id'],'title'=>$work['title'],'number'=>$c['number'],'sourceUrl'=>$r['url'],'chapterUrl'=>$c['url']];q('INSERT INTO notices(message,created_at) VALUES(?,?)',['چپتر '.$c['number'].' از '.$work['title'].' اضافه شد.',$at]);}}return $added;});$result=['added'=>count($added),'chapters'=>$added];
  }
 }else throw new RuntimeException('Usage: php scripts/chapter-watch.php list|pending|ingest FILE|map FILE|recipient EMAIL|sent FILE|record-run FILE');
 echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT).PHP_EOL;
}catch(Throwable $e){fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}
